const form=document.getElementById('magicForm'),notice=document.getElementById('adminLoginNotice'),params=new URLSearchParams(location.search),token=params.get('token');async function api(path,options={}){const response=await fetch(path,{headers:{'Content-Type':'application/json'},...options}),data=await response.json();if(!response.ok){const error=new Error(data.error||'Unable to continue.');error.status=response.status;throw error}return data}function show(message,error=false){notice.textContent=message;notice.hidden=false;notice.classList.toggle('error',error)}function submitState(active){const button=form.querySelector('button');button.disabled=active;button.textContent=active?button.dataset.loading:'Send magic link'}form.addEventListener('submit',async event=>{event.preventDefault();notice.hidden=true;submitState(true);try{const data=await api('/api/admin/magic/request',{method:'POST',body:JSON.stringify({email:new FormData(form).get('email')})});show(data.delivery==='not_configured'?'Admin email delivery is not configured yet. Add the Resend API key in Railway, then try again.':data.delivery==='failed'?'Email delivery had a problem. Please try again shortly.':data.message)}catch(error){show(error.message,true)}finally{submitState(false)}});if(location.pathname==='/admin/verify'){document.getElementById('requestView').hidden=true;document.getElementById('verifyView').hidden=false;if(!token){document.getElementById('verifyMessage').textContent='This owner sign-in link is incomplete.';show('Request a new magic link from the admin sign-in page.',true)}else api('/api/admin/magic/verify',{method:'POST',body:JSON.stringify({token})}).then(()=>location.replace('/admin')).catch(error=>{document.getElementById('verifyMessage').textContent='This sign-in link could not be verified.';show(error.message,true)})}
